-- Migration 006_stats.sql (SHA-256: 8512ceccf9ce3665535cf2b9f023f3697f0d14cba7b1c7c0620f45e81464a9d2)
-- 006 statistics: first-party, no third-party script, no raw IP.
-- The clinic currently learns nothing about its own traffic Ã¢â‚¬â€ WordPress used to.
--
-- Privacy model: a visitor is a salted hash that rotates daily (visitor_hash), the
-- IP is only ever stored hashed, referrer keeps the host and not the full URL, and
-- a request whose UA matches the bot list is recorded with bot=1 and then ignored
-- by every aggregate. Requests sending Sec-GPC or DNT are still counted as views
-- but never get a visitor hash, so they cannot be distinguished from other traffic
-- on later days.

CREATE TABLE stats_events (
  id BIGINT AUTO_INCREMENT PRIMARY KEY,
  day DATE NOT NULL,
  event_type VARCHAR(24) NOT NULL DEFAULT 'pageview',
  path VARCHAR(512) NOT NULL,
  locale VARCHAR(5) NOT NULL DEFAULT '',
  referrer_host VARCHAR(191) NOT NULL DEFAULT '',
  device VARCHAR(16) NOT NULL DEFAULT 'unknown',
  cta_key VARCHAR(120) NOT NULL DEFAULT '',
  visitor_hash CHAR(64) NULL,
  bot TINYINT(1) NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  INDEX stats_day_path (day, path),
  INDEX stats_day_type (day, event_type),
  INDEX stats_created (created_at)
);

CREATE TABLE stats_daily (
  day DATE NOT NULL,
  path VARCHAR(512) NOT NULL,
  locale VARCHAR(5) NOT NULL DEFAULT '',
  views BIGINT NOT NULL DEFAULT 0,
  visitors BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (day, path, locale)
);
CREATE INDEX stats_daily_day ON stats_daily (day);

CREATE TABLE stats_referrers_daily (
  day DATE NOT NULL,
  host VARCHAR(191) NOT NULL,
  views BIGINT NOT NULL DEFAULT 0,
  visitors BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (day, host)
);

CREATE TABLE stats_cta_daily (
  day DATE NOT NULL,
  cta_key VARCHAR(120) NOT NULL,
  clicks BIGINT NOT NULL DEFAULT 0,
  UNIQUE KEY stats_cta_key (day, cta_key)
);

-- Where the rollup got to, so a re-run never double-counts.
CREATE TABLE stats_rollup_state (
  id INT PRIMARY KEY,
  last_event_id BIGINT NOT NULL DEFAULT 0,
  last_run_at DATETIME(3) NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3)
);
INSERT INTO stats_rollup_state (id, last_event_id) VALUES (1, 0);
INSERT INTO app_migrations (name, checksum) VALUES ('006_stats.sql', '8512ceccf9ce3665535cf2b9f023f3697f0d14cba7b1c7c0620f45e81464a9d2');

-- Migration 007_views.sql (SHA-256: 6c650865f13b94c39f99223bafd03a46b32b07b14f4a0305424a26fbb2575337)
-- 007 console views: the filters a person saves for themselves.
--
-- A saved view is a name pasted onto a query string, not a set of columns: the console
-- stores exactly the terms `src/lib/content/list-view.ts` puts in the address bar, so a
-- saved filter and a link shared with a colleague are the same object and re-reading one
-- cannot disagree with the screen it came from.
--
-- `query` holds the whole line, scope terms included (`list=`, `trash=`, `locale=`),
-- because those decide which rows the view was ever run over. Rows belong to one user
-- and every read filters on `user_id`; there is no shared view that could leak a list
-- its owner cannot open. No foreign key, in line with the other tables Ã¢â‚¬â€ the console
-- deletes a person's views when it disables them, and the import order stays free.

CREATE TABLE console_views (
  id CHAR(36) PRIMARY KEY,
  user_id CHAR(36) NOT NULL,
  kind VARCHAR(16) NOT NULL,
  name VARCHAR(80) NOT NULL,
  query VARCHAR(512) NOT NULL,
  position INT NOT NULL DEFAULT 0,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  deleted_at DATETIME(3) NULL,
  version INT NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX console_views_name ON console_views (user_id, kind, name);
CREATE INDEX console_views_owner ON console_views (user_id, kind, position);
INSERT INTO app_migrations (name, checksum) VALUES ('007_views.sql', '6c650865f13b94c39f99223bafd03a46b32b07b14f4a0305424a26fbb2575337');

-- Migration 008_public_indexes.sql (SHA-256: 4b7301df8100b16f79edfa154aa5e7d59104a14b598494d3b0e54c4bf7ced1fe)
-- The public read path filters every list by its publish state and then orders it:
-- articles newest-first by published_at, offers and list items by position, pages by
-- route, categories by position. Before this each read ended in a filesort (articles
-- already had an index on status alone, which covered the filter but not the order).
--
-- Additive only: no existing index is dropped, so a console query that already had a
-- plan keeps it. The leading columns match the WHERE clause in that order Ã¢â‚¬â€ status,
-- then deleted_at Ã¢â‚¬â€ because the site always asks for both.
CREATE INDEX articles_public ON articles (status, deleted_at, published_at, slug);
CREATE INDEX offers_public ON offers (status, deleted_at, position, slug);
CREATE INDEX pages_public ON pages (status, deleted_at, route);
CREATE INDEX list_items_public ON list_items (list_id, status, deleted_at, position, uid);
CREATE INDEX categories_public ON categories (deleted_at, enabled, position);
INSERT INTO app_migrations (name, checksum) VALUES ('008_public_indexes.sql', '4b7301df8100b16f79edfa154aa5e7d59104a14b598494d3b0e54c4bf7ced1fe');

-- Migration 009_hero.sql (SHA-256: 2121a37dc6882a23b106931293190b42dc420db2738e57b3eef74be934c11f73)
-- 009 hero: the homepage slider becomes a row, not a residue of the WordPress page body.
--
-- Until now the hero photos were scraped out of the imported home page's builder HTML.
-- They could not be reordered, captioned, scheduled, or even seen: the console had no
-- screen for them, and a photo could only change by editing the page body someone else
-- wrote. This table is the slider itself: one row per slide, in the order the homepage
-- shows them.
--
-- No draft/pub pair here on purpose. A slide is a background photograph plus optional
-- copy; it has an `active` flag and an optional schedule instead of a publish step, so a
-- saved-but-inactive row is the draft. Publishing a case story and swapping a hero frame
-- are different jobs and should not share a transaction.
--
-- Alt text is NOT NULL and defaulted to '': a slide without alt text still has a picture,
-- and an empty string is the honest way to say "nobody wrote one" (the console refuses to
-- activate such a slide, and the public component then hides it from assistive tech rather
-- than inventing a description).

CREATE TABLE hero_slides (
  id CHAR(36) PRIMARY KEY,
  position INT NOT NULL DEFAULT 0,
  active TINYINT(1) NOT NULL DEFAULT 1,
  image VARCHAR(512) NOT NULL,
  image_mobile VARCHAR(512) NULL,
  alt_ar VARCHAR(255) NOT NULL DEFAULT '',
  alt_en VARCHAR(255) NOT NULL DEFAULT '',
  heading_ar VARCHAR(255) NULL,
  heading_en VARCHAR(255) NULL,
  sub_ar VARCHAR(500) NULL,
  sub_en VARCHAR(500) NULL,
  cta_label_ar VARCHAR(120) NULL,
  cta_label_en VARCHAR(120) NULL,
  cta_href_ar VARCHAR(512) NULL,
  cta_href_en VARCHAR(512) NULL,
  starts_at DATETIME(3) NULL,
  ends_at DATETIME(3) NULL,
  created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  created_by CHAR(36) NULL,
  updated_by CHAR(36) NULL,
  deleted_at DATETIME(3) NULL,
  version INT NOT NULL DEFAULT 1,
  INDEX hero_slides_order (deleted_at, active, position)
);

-- One row, id = 1. The defaults are the behaviour the site already has: seven seconds a
-- slide, a 1.2-second crossfade, loop, pause while the pointer is over it. Controls are
-- off by default because the hero never had any and a full-bleed photograph should not
-- grow chrome just because it became editable.
CREATE TABLE hero_settings (
  id TINYINT PRIMARY KEY,
  autoplay TINYINT(1) NOT NULL DEFAULT 1,
  interval_ms INT NOT NULL DEFAULT 7000,
  fade_ms INT NOT NULL DEFAULT 1200,
  pause_on_hover TINYINT(1) NOT NULL DEFAULT 1,
  dots TINYINT(1) NOT NULL DEFAULT 0,
  arrows TINYINT(1) NOT NULL DEFAULT 0,
  -- `loop` is a MariaDB stored-program keyword; the column is `looping`.
  looping TINYINT(1) NOT NULL DEFAULT 1,
  updated_by CHAR(36) NULL,
  updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  version INT NOT NULL DEFAULT 1
);
INSERT INTO hero_settings (id) VALUES (1);
